package br.com.sussmartcare.triage.infrastructure.projection; import com.fasterxml.jackson.databind.*; import java.time.*; import java.util.*; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class BiometricProjectionConsumer {private final ObjectMapper mapper;private final TriageObservationRepository observations;private final ProcessedEventRepository processed;public BiometricProjectionConsumer(ObjectMapper m,TriageObservationRepository o,ProcessedEventRepository p){mapper=m;observations=o;processed=p;}
 @KafkaListener(topics="biometric-observation-received",groupId="triage-biometric-projection") @Transactional public void consume(String raw)throws Exception{JsonNode e=mapper.readTree(raw);UUID eventId=UUID.fromString(e.path("eventId").asText());if(processed.existsById(eventId))return;JsonNode d=e.path("data");if(d.path("visitId").isNull()||d.path("visitId").asText().isBlank()){processed.save(new ProcessedEvent(eventId,"triage-biometric-projection"));return;}observations.save(new TriageObservation(UUID.fromString(d.path("observationId").asText()),UUID.fromString(d.path("visitId").asText()),d.path("type").asText(),d.path("value").asDouble(),d.path("unit").isMissingNode()?null:d.path("unit").asText(null),Instant.parse(d.path("measuredAt").asText())));processed.save(new ProcessedEvent(eventId,"triage-biometric-projection"));}
}
